优化为单次遍历或缓存结果：
```csharp
var list = AbroadPkgHelper.GetActivePkgList(req.AppGroup).ToList(); // 缓存枚举结果
var activityMaxCouponKind = list.Where(s => s.IsActivity).Select(s => s.CouponKind).DefaultIfEmpty(0).Max();
var mornalMaxCouponKind = list.Where(s => s.CouponKind >= 1000 && s.CouponKind < 2000).Select(s => s.CouponKind).DefaultIfEmpty(0).Max();
var couponMaxCouponKind = list.Where(s => s.CouponKind >= 2000 && s.CouponKind < 3000).Select(s => s.CouponKind).DefaultIfEmpty(0).Max();
var trialMaxCouponKind = list.Where(s => s.CouponKind >= 3000 && s.CouponKind < 4000).Select(s => s.CouponKind).DefaultIfEmpty(0).Max();
var trialBMaxCouponKind = list.Where(s => s.CouponKind >= 4000 && s.CouponKind < 5000).Select(s => s.CouponKind).DefaultIfEmpty(0).Max();
```
或者使用单次遍历：
```csharp
int? activityMaxCouponKind = null, mornalMaxCouponKind = null, couponMaxCouponKind = null, trialMaxCouponKind = null, trialBMaxCouponKind = null;
foreach (var item in list)
{
    if (item.IsActivity) activityMaxCouponKind = Math.Max(activityMaxCouponKind ?? 0, item.CouponKind);
    if (item.CouponKind >= 1000 && item.CouponKind < 2000) mornalMaxCouponKind = Math.Max(mornalMaxCouponKind ?? 0, item.CouponKind);
    if (item.CouponKind >= 2000 && item.CouponKind < 3000) couponMaxCouponKind = Math.Max(couponMaxCouponKind ?? 0, item.CouponKind);
    if (item.CouponKind >= 3000 && item.CouponKind < 4000) trialMaxCouponKind = Math.Max(trialMaxCouponKind ?? 0, item.CouponKind);
    if (item.CouponKind >= 4000 && item.CouponKind < 5000) trialBMaxCouponKind = Math.Max(trialBMaxCouponKind ?? 0, item.CouponKind);
}
```

优化为并行执行和统一处理：
```csharp
var googleLocalPriceTasks = new List<Task>();

// 收集所有需要创建的Google本地价格
var googlePriceItems = new List<(string OfferId, string ProductId)>();
if (!string.IsNullOrEmpty(req.MonthPkg.ActivityOfferId)) googlePriceItems.Add((req.MonthPkg.ActivityOfferId, req.MonthPkg.GoogleProductId));
if (!string.IsNullOrEmpty(req.MonthPkg.CouponOfferId)) googlePriceItems.Add((req.MonthPkg.CouponOfferId, req.MonthPkg.GoogleProductId));
if (!string.IsNullOrEmpty(req.MonthPkg.TrialOfferId)) googlePriceItems.Add((req.MonthPkg.TrialOfferId, req.MonthPkg.GoogleProductId));
if (!string.IsNullOrEmpty(req.MonthPkg.TrialBOfferId)) googlePriceItems.Add((req.MonthPkg.TrialBOfferId, req.MonthPkg.GoogleProductId));
// ... 类似处理 Quarter 和 Year

// 并行执行
if (googlePriceItems.Count > 0)
{
    var tasks = googlePriceItems.Select(item => 
        GooglePlayService.GetLocalPrice(req.AppGroup, item.ProductId, item.OfferId)
            .ContinueWith(t => {
                if (t.IsFaulted)
                    Logger.Error(t.Exception, "创建Google本地价格失败: AppGroup={AppGroup}, ProductId={ProductId}, OfferId={OfferId}", req.AppGroup, item.ProductId, item.OfferId);
            }));
    await Task.WhenAll(tasks).ConfigureAwait(false);
}
```

